import React, { useEffect, useRef, useState } from 'react';
import {
  IonPage,
  IonContent,
  IonButton,
  IonIcon,
  IonInput,
  IonItem,
  IonToast,
  IonSpinner,
} from '@ionic/react';
import {
  mailOutline,
  lockClosedOutline,
  eyeOutline,
  eyeOffOutline,
  phonePortraitOutline,
  logoGoogle,
  logoApple,
} from 'ionicons/icons';
import { useNavigate } from 'react-router-dom';
import { authApi, tokenStorage } from '@services/api';
import {
  SignupRequestSchema,
  LoginRequestSchema,
  OtpSendRequestSchema,
  VerifyOtpRequestSchema,
} from '@utils/schemas';
import useAppStore from '@store/useAppStore';

const isEmail = (value) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);

const Auth = () => {
  const navigate = useNavigate();
  const setAuthUser = useAppStore((s) => s.setAuthUser);

  const [mode, setMode] = useState('login'); // 'login' | 'signup' | 'otp'
  const [identifier, setIdentifier] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [otp, setOtp] = useState('');
  const [loading, setLoading] = useState(false);
  const [toast, setToast] = useState({ open: false, message: '', color: 'danger' });

  // OTP resend countdown
  const [retryAfter, setRetryAfter] = useState(0);
  const countdownRef = useRef(null);

  useEffect(() => {
    return () => {
      if (countdownRef.current) clearInterval(countdownRef.current);
    };
  }, []);

  const startCountdown = (seconds) => {
    if (countdownRef.current) clearInterval(countdownRef.current);
    setRetryAfter(seconds);
    countdownRef.current = setInterval(() => {
      setRetryAfter((prev) => {
        if (prev <= 1) {
          clearInterval(countdownRef.current);
          return 0;
        }
        return prev - 1;
      });
    }, 1000);
  };

  const finishAuth = (data) => {
    tokenStorage.set(data.accessToken, data.refreshToken);
    setAuthUser(data);
    if (data.isNewUser) {
      navigate('/profile-wizard', { replace: true });
    } else {
      navigate('/discover', { replace: true });
    }
  };

  const extractError = (error) => {
    if (error?.response?.data?.message) {
      const msg = error.response.data.message;
      return Array.isArray(msg) ? msg[0] : msg;
    }
    return error?.message || 'Something went wrong. Please try again.';
  };

  const handleLogin = async () => {
    try {
      LoginRequestSchema.parse({ identifier, password });
    } catch (err) {
      setToast({ open: true, message: err.errors?.[0]?.message || 'Invalid input', color: 'danger' });
      return;
    }
    setLoading(true);
    try {
      const { data } = await authApi.login(identifier.trim(), password);
      finishAuth(data);
    } catch (err) {
      setToast({ open: true, message: extractError(err), color: 'danger' });
    } finally {
      setLoading(false);
    }
  };

  const handleSignup = async () => {
    const trimmed = identifier.trim();
    const payload = isEmail(trimmed)
      ? { email: trimmed, password }
      : { phone: trimmed, password };
    try {
      SignupRequestSchema.parse(payload);
    } catch (err) {
      setToast({ open: true, message: err.errors?.[0]?.message || 'Invalid input', color: 'danger' });
      return;
    }
    setLoading(true);
    try {
      const { data } = await authApi.signup(payload);
      tokenStorage.set(data.accessToken, data.refreshToken);
      setAuthUser(data);
      await authApi.sendOtp(trimmed, 'signup');
      setMode('otp');
      setToast({ open: true, message: 'Verification code sent', color: 'success' });
      startCountdown(30);
    } catch (err) {
      setToast({ open: true, message: extractError(err), color: 'danger' });
    } finally {
      setLoading(false);
    }
  };

  const handleResendOtp = async () => {
    const trimmed = identifier.trim();
    try {
      OtpSendRequestSchema.parse({ identifier: trimmed, purpose: 'signup' });
    } catch (err) {
      setToast({ open: true, message: err.errors?.[0]?.message || 'Invalid identifier', color: 'danger' });
      return;
    }
    setLoading(true);
    try {
      const { data } = await authApi.sendOtp(trimmed, 'signup');
      setToast({ open: true, message: data.message || 'Code resent', color: 'success' });
      startCountdown(data.retryAfterSeconds ?? 30);
    } catch (err) {
      setToast({ open: true, message: extractError(err), color: 'danger' });
    } finally {
      setLoading(false);
    }
  };

  const handleVerifyOtp = async () => {
    const trimmed = identifier.trim();
    try {
      VerifyOtpRequestSchema.parse({ identifier: trimmed, code: otp, purpose: 'signup' });
    } catch (err) {
      setToast({ open: true, message: err.errors?.[0]?.message || 'Enter the 6-digit code', color: 'danger' });
      return;
    }
    setLoading(true);
    try {
      const { data } = await authApi.verifyOtp(trimmed, otp, 'signup');
      finishAuth(data);
    } catch (err) {
      setToast({ open: true, message: extractError(err), color: 'danger' });
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    if (mode === 'login') handleLogin();
    else if (mode === 'signup') handleSignup();
    else handleVerifyOtp();
  };

  const handleSocialLogin = (provider) => {
    setToast({ open: true, message: `${provider} login coming soon`, color: 'primary' });
  };

  const switchMode = (next) => {
    setMode(next);
    setPassword('');
    setOtp('');
    setToast({ open: false });
  };

  const titles = {
    login: 'Welcome Back',
    signup: 'Create Account',
    otp: 'Verify Your Number',
  };

  return (
    <IonPage>
      <IonContent fullscreen className="ion-padding">
        <div className="mx-auto flex min-h-[100dvh] max-w-md flex-col justify-center py-10">
          {/* Logo mark */}
          <div className="mb-8 text-center">
            <div className="mx-auto mb-4 grid h-16 w-16 place-items-center rounded-3xl bg-gradient-to-br from-primary to-secondary shadow-xl shadow-primary/30">
              <span className="text-2xl">💑</span>
            </div>
            <h1 className="text-2xl font-black text-foreground">{titles[mode]}</h1>
            <p className="mt-1.5 text-sm text-gray-500 dark:text-gray-400">
              {mode === 'otp'
                ? 'Enter the 6-digit code sent to your phone'
                : mode === 'login'
                ? 'Sign in to continue to Dinanwuye'
                : 'Join thousands finding meaningful connections'}
            </p>
          </div>

          <form onSubmit={handleSubmit} className="space-y-3">
            {(mode === 'login' || mode === 'signup') && (
              <>
                <IonItem lines="none">
                  <IonIcon
                    icon={isEmail(identifier) ? mailOutline : phonePortraitOutline}
                    slot="start"
                    color="medium"
                  />
                  <IonInput
                    type="text"
                    inputMode={isEmail(identifier) ? 'email' : 'tel'}
                    placeholder="Email or phone (+234...)"
                    value={identifier}
                    onIonChange={(e) => setIdentifier(e.detail.value ?? '')}
                    required
                    autoComplete="username"
                  />
                </IonItem>
                <IonItem lines="none">
                  <IonIcon icon={lockClosedOutline} slot="start" color="medium" />
                  <IonInput
                    type={showPassword ? 'text' : 'password'}
                    placeholder="Password"
                    value={password}
                    onIonChange={(e) => setPassword(e.detail.value ?? '')}
                    required
                    autoComplete={mode === 'login' ? 'current-password' : 'new-password'}
                  >
                    <IonIcon
                      icon={showPassword ? eyeOffOutline : eyeOutline}
                      slot="end"
                      onClick={() => setShowPassword(!showPassword)}
                      color="medium"
                    />
                  </IonInput>
                </IonItem>
              </>
            )}

            {mode === 'otp' && (
              <>
                <IonItem lines="none">
                  <IonIcon icon={lockClosedOutline} slot="start" color="medium" />
                  <IonInput
                    type="text"
                    placeholder="000000"
                    value={otp}
                    onIonChange={(e) => setOtp((e.detail.value ?? '').replace(/\D/g, ''))}
                    required
                    autoComplete="one-time-code"
                    inputMode="numeric"
                    maxLength={6}
                    style={{ letterSpacing: '0.5rem', textAlign: 'center', fontSize: '1.5rem' }}
                  />
                </IonItem>
                <div className="text-center text-sm">
                  {retryAfter > 0 ? (
                    <span className="text-gray-500">Resend code in {retryAfter}s</span>
                  ) : (
                    <button
                      type="button"
                      className="text-primary font-medium"
                      onClick={handleResendOtp}
                      disabled={loading}
                    >
                      Resend code
                    </button>
                  )}
                </div>
              </>
            )}

            <IonButton
              type="submit"
              expand="block"
              size="large"
              color="primary"
              className="touch-target-comfortable mt-2"
              disabled={loading}
            >
              {loading ? (
                <IonSpinner name="crescent" />
              ) : mode === 'otp' ? (
                'Verify'
              ) : mode === 'login' ? (
                'Sign In'
              ) : (
                'Create Account'
              )}
            </IonButton>
          </form>

          <div className="mt-6 flex items-center gap-4">
            <div className="flex-1 border-t border-gray-200" />
            <span className="text-sm text-gray-500">or continue with</span>
            <div className="flex-1 border-t border-gray-200" />
          </div>

          <div className="mt-4 grid grid-cols-2 gap-3">
            <IonButton
              fill="outline"
              size="large"
              color="primary"
              className="touch-target-comfortable"
              onClick={() => handleSocialLogin('Google')}
            >
              <IonIcon icon={logoGoogle} slot="start" style={{ fontSize: '1.5rem' }} />
              Google
            </IonButton>
            <IonButton
              fill="outline"
              size="large"
              color="primary"
              className="touch-target-comfortable"
              onClick={() => handleSocialLogin('Apple')}
            >
              <IonIcon icon={logoApple} slot="start" style={{ fontSize: '1.5rem' }} />
              Apple
            </IonButton>
          </div>

          <p className="mt-6 text-center text-sm text-gray-600">
            {mode === 'login' ? (
              <>
                Don&apos;t have an account?{' '}
                <button className="text-primary font-medium" onClick={() => switchMode('signup')}>
                  Sign Up
                </button>
              </>
            ) : mode === 'signup' ? (
              <>
                Already have an account?{' '}
                <button className="text-primary font-medium" onClick={() => switchMode('login')}>
                  Sign In
                </button>
              </>
            ) : (
              <button className="text-primary font-medium" onClick={() => switchMode('login')}>
                Use a different account
              </button>
            )}
          </p>
        </div>

        <IonToast
          isOpen={toast.open}
          onDidDismiss={() => setToast({ ...toast, open: false })}
          message={toast.message}
          duration={4000}
          position="bottom"
          color={toast.color}
        />
      </IonContent>
    </IonPage>
  );
};

export default Auth;
